import{c as a,Q as e,j as i,m as r}from"./chunks/framework.D55kK6e8.js";const u=JSON.parse('{"title":"工单管理","description":"","frontmatter":{},"headers":[],"relativePath":"guide/ticket-management.md","filePath":"guide/ticket-management.md"}'),d={name:"guide/ticket-management.md"};function l(n,t,s,o,c,h){return e(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="工单管理" tabindex="-1">工单管理 <a class="header-anchor" href="#工单管理" aria-label="Permalink to &quot;工单管理&quot;">​</a></h1><p>工单管理是系统的核心功能，提供完整的工单生命周期管理。</p><h2 id="创建工单" tabindex="-1">创建工单 <a class="header-anchor" href="#创建工单" aria-label="Permalink to &quot;创建工单&quot;">​</a></h2><p>访问 <code>/tickets/create</code> 页面，填写以下信息：</p><ul><li><strong>工单标题</strong>（必填）- 简短描述问题</li><li><strong>工单描述</strong>（必填）- 详细说明问题情况</li><li><strong>工单类型</strong> - 日常维护、技术支持、财务问题、功能请求、故障报告、其他</li><li><strong>优先级</strong> - 低、中、高、紧急</li><li><strong>申请科室</strong>（必填）- 选择所属科室</li><li><strong>联系电话</strong>（可选）</li><li><strong>位置/房间号</strong>（可选）</li><li><strong>紧急说明</strong>（可选）</li></ul><h2 id="工单列表" tabindex="-1">工单列表 <a class="header-anchor" href="#工单列表" aria-label="Permalink to &quot;工单列表&quot;">​</a></h2><p>访问 <code>/tickets</code> 查看所有工单，支持：</p><ul><li><strong>状态筛选</strong> - 待处理、处理中、已解决、已关闭</li><li><strong>搜索功能</strong> - 按标题、描述、编号搜索</li><li><strong>排序</strong> - 按优先级、状态、创建时间排序</li></ul><h2 id="工单详情" tabindex="-1">工单详情 <a class="header-anchor" href="#工单详情" aria-label="Permalink to &quot;工单详情&quot;">​</a></h2><p>点击工单列表中的任意工单，查看详细信息和状态历史，包括：</p><ul><li>工单基本信息</li><li>处理信息（处理人、处理结果）</li><li>时间线（创建、更新、关闭记录）</li></ul><h2 id="状态流转" tabindex="-1">状态流转 <a class="header-anchor" href="#状态流转" aria-label="Permalink to &quot;状态流转&quot;">​</a></h2><p>工单状态遵循以下流转规则：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>待处理 → 处理中 → 已解决 → 已关闭</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">提示</p><p>只有创建者、处理人或管理员可以编辑工单。</p></div><h2 id="权限控制" tabindex="-1">权限控制 <a class="header-anchor" href="#权限控制" aria-label="Permalink to &quot;权限控制&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>创建者</th><th>处理人</th><th>管理员</th></tr></thead><tbody><tr><td>查看</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>编辑</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>删除</td><td>✅</td><td>❌</td><td>✅</td></tr><tr><td>状态变更</td><td>✅</td><td>✅</td><td>✅</td></tr></tbody></table>',17)])])}const g=a(d,[["render",l]]);export{u as __pageData,g as default};
